(* LPS 727298f3: [AllocRepX.AGAP_of_akernel]'s room premise gains what the launch's vDSO/vvar pair
   costs the ledger, [81920 + 2 * (msz + 4096)].  [AS_SecSum.agap_arith] with that term added to
   its conclusion; the same proof, the slack (above 10^13) absorbs it.  [inst_malloc_stmt]'s
   recorded room proof uses this lemma and [agap_glue_w] where it used [agap_arith] and a
   recorded arithmetic step. *)
Lemma agap_arith_w : forall K Kl Kq Sl n L msz hc : Z,
  0 <= Kl -> 0 <= Kq -> 0 <= K <= Kl + Kq -> 64513 * Kl <= L - n -> 64521 * Kq <= 269484032 ->
  1 <= n <= 2 ^ 31 -> 0 <= L <= 2 ^ 32 + 2 ^ 28 -> 0 <= Sl <= L - n + 12294 * Kl ->
  0 < msz <= n + 12294 -> 140735332483072 <= hc ->
  17594333495296 + (2 ^ 38 + (Sl + (2 ^ 32 + 2 ^ 14) * Kq)) + (32 + K) * (msz + 4096) + msz
    + (81920 + 2 * (msz + 4096)) <= hc.
Proof.
  intros K Kl Kq Sl n L msz hc HKl HKq HK HL HQ Hn HLb HS HM Hc.
  set (x := n + 16390).
  set (P := (32 + K) * (msz + 4096)).
  assert (P1 : P <= (32 + K) * x) by (subst P x; apply Z.mul_le_mono_nonneg_l; lia).
  set (Wc := 271564838 + L).
  assert (P2 : 64513 * ((32 + K) * x) <= (Wc - x) * x).
  { replace (64513 * ((32 + K) * x)) with ((64513 * 32 + 64513 * K) * x) by ring.
    apply Z.mul_le_mono_nonneg_r; [subst x; lia|]. subst Wc x. lia. }
  assert (P3 : 4 * ((Wc - x) * x) <= Wc * Wc).
  { assert (E : Wc * Wc - 4 * ((Wc - x) * x) = (Wc - 2 * x) * (Wc - 2 * x)) by ring.
    pose proof (Z.square_nonneg (Wc - 2 * x)). lia. }
  assert (P4 : Wc * Wc <= 4834967590 * 4834967590).
  { apply Z.mul_le_mono_nonneg; subst Wc; lia. }
  assert (P5 : 258052 * P <= 4834967590 * 4834967590) by lia.
  clear P1 P2 P3 P4. clearbody P. subst x Wc. lia.
Qed.
(* The arithmetic step of that room proof, with the same term on both sides. *)
Lemma agap_glue_w : forall (P : Prop) (x8 x7 x6 x5 x4 x3 x2 x1 : Z),
  17594333495296 + (2 ^ 38 + ((x6 + 12294 * x7) + (2 ^ 32 + 2 ^ 14) * x8)) + (32 + x2) * (x3 + 4096) + x3
    + (81920 + 2 * (x3 + 4096)) <= x4 ->
  P /\ x1 <= x5 ->
  x5 <= (x6 + 12294 * x7) + (2 ^ 32 + 2 ^ 14) * x8 ->
  17594333495296 + (2 ^ 38 + x1) + (32 + x2) * (x3 + 4096) + x3 + (81920 + 2 * (x3 + 4096)) <= x4.
Proof. intros P x8 x7 x6 x5 x4 x3 x2 x1 H1 [_ H2] H3. lia. Qed.

